// src/bin/bifrost-backup.rs

use std::{
    path::PathBuf,
    thread,
    time::Duration,
};
use clap::{Parser, ValueEnum};
use log::{info, warn};

use bifrost::backup;

/// Bifrost Backup Executor
///
/// Executes backup operations based on control files generated by the scanner.
#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
struct Args {
    /// Source base directory (used to construct source file paths)
    #[arg(long, short = 's', required = true, value_name = "DIR")]
    source_dir: PathBuf,

    /// Target base directory for backup output (local FS; ignored when --nfs-target-host is set)
    #[arg(long, short = 't', required = true, value_name = "DIR")]
    target_dir: PathBuf,

    /// Metadata directory containing meta_*.dat files
    #[arg(long, short = 'm', required = true, value_name = "DIR")]
    meta_dir: PathBuf,

    /// Control file path (generated by bifrost-scan)
    #[arg(long, short = 'c', required = true, value_name = "FILE")]
    control_file: PathBuf,
    
    /// Control directory containing hardlink.txt (optional)
    #[arg(long, value_name = "DIR")]
    ctrl_dir: Option<PathBuf>,
    
    /// Enable hardlink phase after copy phase
    #[arg(long, action = clap::ArgAction::SetTrue)]
    hardlink: bool,
    
    /// Enable delete phase after hardlink phase
    #[arg(long, action = clap::ArgAction::SetTrue)]
    delete: bool,
    
    /// Enable mtime phase after copy/hardlink phase
    #[arg(long, action = clap::ArgAction::SetTrue)]
    mtime: bool,

    /// Enable aggregate backup mode (combines small files into blobs)
    #[arg(long, action = clap::ArgAction::SetTrue)]
    aggregate: bool,

    /// Maximum size of aggregate blob files in MB (default: 64)
    #[arg(long, value_name = "SIZE_MB", default_value = "64")]
    max_blob_size: u64,

    /// File size threshold for aggregation in KB (files smaller than this are aggregated, default: 1024)
    #[arg(long, value_name = "SIZE_KB", default_value = "1024")]
    aggregate_threshold: u64,

    /// Directory for aggregate index and blob files (default: target_dir)
    #[arg(long, value_name = "DIR")]
    aggregate_dir: Option<PathBuf>,

    // ── NFS target options (require the `nfs` feature) ───────────────────
    /// NFS target: server IP or hostname (e.g. 192.168.1.10).
    /// When set, files are written to the NFS server via the AIO pipeline
    /// instead of the local --target-dir.
    /// Requires the binary to be built with --features nfs.
    #[arg(long, value_name = "HOST", requires = "nfs_target_export")]
    nfs_target_host: Option<String>,

    /// NFS target: export path on the server (e.g. /export/backup).
    #[arg(long, value_name = "PATH", requires = "nfs_target_host")]
    nfs_target_export: Option<String>,

    /// NFS target: sub-path within the export to use as the working root.
    /// Defaults to the export root when not specified.
    #[arg(long, value_name = "PATH")]
    nfs_target_sub_path: Option<String>,

    /// NFS target: number of parallel TCP connections (default: 4).
    #[arg(long, value_name = "N", default_value = "4")]
    nfs_target_connections: usize,

    /// Verbose logging
    #[arg(short, long, action = clap::ArgAction::Count)]
    verbose: u8,
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = Args::parse();

    // Initialize logging
    let log_level = match args.verbose {
        0 => log::LevelFilter::Info,
        1 => log::LevelFilter::Debug,
        _ => log::LevelFilter::Trace,
    };
    env_logger::Builder::new()
        .filter_level(log_level)
        .init();

    // Validate input paths
    if !args.meta_dir.exists() {
        return Err(format!("Metadata directory does not exist: {}", args.meta_dir.display()).into());
    }
    if !args.control_file.exists() {
        return Err(format!("Control file does not exist: {}", args.control_file.display()).into());
    }

    // Determine control directory
    let ctrl_dir = args.ctrl_dir.unwrap_or_else(|| {
        args.control_file.parent().unwrap_or(&args.meta_dir).to_path_buf()
    });

    // Create backup option and task
    let mut backup_option = crate::backup::BackupOption::new(
        args.source_dir.clone(),
        args.target_dir.clone(),
        args.meta_dir,
        ctrl_dir,
        args.control_file,
    ).enable_hardlink_phase(args.hardlink)
     .enable_delete_phase(args.delete)
     .enable_mtime_phase(args.mtime);

    // Configure aggregation if enabled
    if args.aggregate {
        let max_blob_size = args.max_blob_size * 1024 * 1024; // Convert MB to bytes
        let aggregate_threshold = args.aggregate_threshold * 1024; // Convert KB to bytes
        backup_option = backup_option
            .enable_aggregation(true)
            .aggregate_max_blob_size(max_blob_size)
            .aggregate_file_threshold(aggregate_threshold);
        info!("Aggregate backup enabled: max_blob_size={}MB, threshold={}KB",
              args.max_blob_size, args.aggregate_threshold);
    }

    // Configure NFS target if requested (requires the `nfs` feature)
    #[cfg(feature = "nfs")]
    if let Some(ref host) = args.nfs_target_host {
        let export = args.nfs_target_export.as_deref().unwrap_or("");
        let mut loc = bifrost::nfs::NfsLocation::new(host, export)
            .connection_count(args.nfs_target_connections);
        if let Some(ref sub) = args.nfs_target_sub_path {
            loc = loc.sub_path(sub);
        }
        info!(
            "NFS target: {}:{} sub_path={:?} connections={}",
            host, export,
            args.nfs_target_sub_path.as_deref().unwrap_or(""),
            args.nfs_target_connections,
        );
        backup_option = backup_option.nfs_target(loc);
    }

    #[cfg(not(feature = "nfs"))]
    if args.nfs_target_host.is_some() {
        return Err("NFS target requested but binary was built without the `nfs` feature.\n\
                    Rebuild with: cargo build --features nfs".into());
    }
    
    let backup_task: backup::BackupTask = backup_option.into();
    
    info!("Starting backup task");
    let running_backup = backup_task.start().expect("backup task start failed");

    // Monitor progress until completion
    loop {
        let stats = running_backup.stats();
        println!(
            "Copied: {} files ({} bytes), Created: {} dirs, Failed: {} files/{} dirs",
            stats.files_copied,
            stats.bytes_copied,
            stats.dirs_created,
            stats.files_failed,
            stats.dirs_failed
        );

        if running_backup.complete() {
            break;
        }
        thread::sleep(Duration::from_secs(1));
    }

    // Final stats and cleanup
    let final_stats = running_backup.stats();
    info!(
        "Backup completed! Total: {} files ({} GB), {} directories",
        final_stats.files_copied,
        final_stats.bytes_copied as f64 / (1024.0 * 1024.0 * 1024.0),
        final_stats.dirs_created
    );

    running_backup.wait().expect("backup task failed unexpectly");
    Ok(())
}